/* white-villa: the logo leads the home hero (client note 9): big logo, smaller statement */
body .e-con.zs-hero--home .zs-hero__logo img{max-height:none;width:min(15vw,19svh,230px);height:auto}
@media (max-width:767px){body .e-con.zs-hero--home .zs-hero__logo img{width:min(44vw,170px)}}
@media (max-height:700px) and (min-width:768px){body .e-con.zs-hero--home .zs-hero__text{row-gap:8px;--row-gap:8px}}
